184	function trim(str: string) {
185	    return str.replace(/^\s\s*/, '').replace(/\s\s*$/, '');
186	}
187	/**
188	 * If a block is tsv format
189	 */
190	function isTSVFormat(block: string): boolean {
191	    // Simple method to find out if a block is tsv format
192	    const firstLine = block.slice(0, block.indexOf('\n'));
193	    if (firstLine.indexOf(ITEM_SPLITER) >= 0) {
194	        return true;
195	    }
196	}
197	
198	const itemSplitRegex = new RegExp('[' + ITEM_SPLITER + ']+', 'g');
199	/**
200	 * @param {string} tsv
201	 * @return {Object}
202	 */
203	function parseTSVContents(tsv: string) {
204	    const tsvLines = tsv.split(/\n+/g);
205	    const headers = trim(tsvLines.shift()).split(itemSplitRegex);
206	
207	    const categories: string[] = [];
208	    const series: {name: string, data: string[]}[] = zrUtil.map(headers, function (header) {
209	        return {
210	            name: header,
211	            data: []
212	        };
213	    });
214	    for (let i = 0; i < tsvLines.length; i++) {
215	        const items = trim(tsvLines[i]).split(itemSplitRegex);
216	        categories.push(items.shift());
217	        for (let j = 0; j < items.length; j++) {
218	            series[j] && (series[j].data[i] = items[j]);
219	        }
220	    }
221	    return {
222	        series: series,
223	        categories: categories
224	    };
225	}
226	
227	function parseListContents(str: string) {
228	    const lines = str.split(/\n+/g);
229	    const seriesName = trim(lines.shift());
230	
231	    const data: DataList = [];
232	    for (let i = 0; i < lines.length; i++) {
233	        // if line is empty, ignore it.
234	        // there is a case that a user forgot to delete `\n`.
235	        const line = trim(lines[i]);
236	        if (!line) {
237	            continue;
238	        }
239	        let items = line.split(itemSplitRegex);
240	
241	        let name = '';
242	        let value: number[];
243	        let hasName = false;
244	        if (isNaN(items[0] as unknown as number)) { // First item is name
245	            hasName = true;
246	            name = items[0];
247	            items = items.slice(1);
248	            data[i] = {
249	                name: name,
250	                value: []
251	            };
252	            value = (data[i] as DataItem).value as number[];
253	        }
254	        else {
255	            value = data[i] = [];
256	        }
257	        for (let j = 0; j < items.length; j++) {
258	            value.push(+items[j]);
259	        }
260	        if (value.length === 1) {
261	            hasName ? ((data[i] as DataItem).value = value[0]) : (data[i] = value[0]);
262	        }
263	    }
264	
265	    return {
266	        name: seriesName,
267	        data: data
268	    };
269	}
270	
271	function parseContents(str: string, blockMetaList: SeriesGroupMeta[]) {
272	    const blocks = str.split(new RegExp('\n*' + BLOCK_SPLITER + '\n*', 'g'));
273	    const newOption: ECUnitOption = {
274	        series: []
275	    };
276	    zrUtil.each(blocks, function (block, idx) {
277	        if (isTSVFormat(block)) {
278	            const result = parseTSVContents(block);
279	            const blockMeta = blockMetaList[idx];
280	            const axisKey = blockMeta.axisDim + 'Axis';
281	
282	            if (blockMeta) {
283	                newOption[axisKey] = newOption[axisKey] || [];
284	                (newOption[axisKey] as any)[blockMeta.axisIndex] = {
285	                    data: result.categories
286	                };
287	                newOption.series = (newOption.series as SeriesOption[]).concat(result.series);
288	            }
289	        }
290	        else {
291	            const result = parseListContents(block);
292	            (newOption.series as SeriesOption[]).push(result);
293	        }
294	    });
295	    return newOption;
296	}
