318	class DataView extends ToolboxFeature<ToolboxDataViewFeatureOption> {
319	
320	    private _dom: HTMLDivElement;
321	
322	    onclick(ecModel: GlobalModel, api: ExtensionAPI) {
323	        // FIXME: better way?
324	        setTimeout(() => {
325	            api.dispatchAction({
326	                type: 'hideTip'
327	            });
328	        });
329	
330	        const container = api.getDom();
331	        const model = this.model;
332	        if (this._dom) {
333	            container.removeChild(this._dom);
334	        }
335	        const root = document.createElement('div');
336	        // use padding to avoid 5px whitespace
337	        root.style.cssText = 'position:absolute;top:0;bottom:0;left:0;right:0;padding:5px';
338	        root.style.backgroundColor = model.get('backgroundColor') || tokens.color.neutral00;
339	
340	        // Create elements
341	        const header = document.createElement('h4');
342	        const lang = model.get('lang') || [];
343	        header.innerHTML = lang[0] || model.get('title');
344	        header.style.cssText = 'margin:10px 20px';
345	        header.style.color = model.get('textColor');
346	
347	        const viewMain = document.createElement('div');
348	        const textarea = document.createElement('textarea');
349	        viewMain.style.cssText = 'overflow:auto';
350	
351	        const optionToContent = model.get('optionToContent');
352	        const contentToOption = model.get('contentToOption');
353	        const result = getContentFromModel(ecModel);
354	        if (zrUtil.isFunction(optionToContent)) {
355	            const htmlOrDom = optionToContent(api.getOption());
356	            if (zrUtil.isString(htmlOrDom)) {
357	                viewMain.innerHTML = htmlOrDom;
358	            }
359	            else if (zrUtil.isDom(htmlOrDom)) {
360	                viewMain.appendChild(htmlOrDom);
361	            }
362	        }
363	        else {
364	            // Use default textarea
365	            textarea.readOnly = model.get('readOnly');
366	            const style = textarea.style;
367	            // eslint-disable-next-line max-len
368	            style.cssText = 'display:block;width:100%;height:100%;font-family:monospace;font-size:14px;line-height:1.6rem;resize:none;box-sizing:border-box;outline:none';
369	            style.color = model.get('textColor');
370	            style.borderColor = model.get('textareaBorderColor');
371	            style.backgroundColor = model.get('textareaColor');
372	            textarea.value = result.value;
373	            viewMain.appendChild(textarea);
374	        }
375	
376	        const blockMetaList = result.meta;
377	
378	        const buttonContainer = document.createElement('div');
379	        buttonContainer.style.cssText = 'position:absolute;bottom:5px;left:0;right:0';
380	
381	        // eslint-disable-next-line max-len
382	        let buttonStyle = 'float:right;margin-right:20px;border:none;cursor:pointer;padding:2px 5px;font-size:12px;border-radius:3px';
383	        const closeButton = document.createElement('div');
384	        const refreshButton = document.createElement('div');
385	
386	        buttonStyle += ';background-color:' + model.get('buttonColor');
387	        buttonStyle += ';color:' + model.get('buttonTextColor');
388	
389	        const self = this;
390	
391	        function close() {
392	            container.removeChild(root);
393	            self._dom = null;
394	        }
395	        addEventListener(closeButton, 'click', close);
396	
397	        addEventListener(refreshButton, 'click', function () {
398	            if ((contentToOption == null && optionToContent != null)
399	                || (contentToOption != null && optionToContent == null)) {
400	                if (__DEV__) {
401	                    // eslint-disable-next-line
402	                    warn('It seems you have just provided one of `contentToOption` and `optionToContent` functions but missed the other one. Data change is ignored.')
403	                }
404	                close();
405	                return;
406	            }
407	
408	            let newOption;
409	            try {
410	                if (zrUtil.isFunction(contentToOption)) {
411	                    newOption = contentToOption(viewMain, api.getOption());
412	                }
413	                else {
414	                    newOption = parseContents(textarea.value, blockMetaList);
415	                }
416	            }
417	            catch (e) {
418	                close();
419	                throw new Error('Data view format error ' + e);
420	            }
421	            if (newOption) {
422	                api.dispatchAction({
423	                    type: 'changeDataView',
424	                    newOption: newOption
425	                });
426	            }
427	
428	            close();
429	        });
430	
431	        closeButton.innerHTML = lang[1];
432	        refreshButton.innerHTML = lang[2];
433	        refreshButton.style.cssText =
434	        closeButton.style.cssText = buttonStyle;
435	
436	        !model.get('readOnly') && buttonContainer.appendChild(refreshButton);
437	        buttonContainer.appendChild(closeButton);
438	
439	        root.appendChild(header);
440	        root.appendChild(viewMain);
441	        root.appendChild(buttonContainer);
442	
443	        viewMain.style.height = (container.clientHeight - 80) + 'px';
444	
445	        container.appendChild(root);
446	        this._dom = root;
447	    }
