508	echarts.registerAction({
509	    type: 'changeDataView',
510	    event: 'dataViewChanged',
511	    update: 'prepareAndUpdate'
512	}, function (payload: ChangeDataViewPayload, ecModel: GlobalModel) {
513	    const newSeriesOptList: SeriesOption[] = [];
514	    zrUtil.each(payload.newOption.series, function (seriesOpt) {
515	        const seriesModel = ecModel.getSeriesByName(seriesOpt.name)[0];
516	        if (!seriesModel) {
517	            // New created series
518	            // Geuss the series type
519	            newSeriesOptList.push(zrUtil.extend({
520	                // Default is scatter
521	                type: 'scatter'
522	            }, seriesOpt));
523	        }
524	        else {
525	            const originalData = seriesModel.get('data');
526	            newSeriesOptList.push({
527	                name: seriesOpt.name,
528	                data: tryMergeDataOption(seriesOpt.data as DataList, originalData as DataList)
529	            });
530	        }
531	    });
532	
533	    ecModel.mergeOption(zrUtil.defaults({
534	        series: newSeriesOptList
535	    }, payload.newOption));
536	});
